import React from 'react';
import { Link } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import './Home.css';
import ProjectCard from '../components/ProjectCard';
import heroImg from '../assets/images/concord.png';

const Home = () => {
  const { t } = useTranslation();

  const focusAreas = t('home.focus.items', { returnObjects: true });
  const skills = t('home.skills.groups', { returnObjects: true });
  const featuredProjects = t('projects.items', { returnObjects: true }).slice(0, 2);
  const serviceHighlights = t('home.cta.highlights', { returnObjects: true });

  return (
    <main className="home-page">
      <section className="home-hero">
        <div className="page-shell home-hero__grid">
          <div className="home-hero__copy">
            <span className="eyebrow">{t('home.eyebrow')}</span>
            <h1 className="page-title home-hero__title">{t('home.title')}</h1>
            <p className="page-lead home-hero__lead">{t('home.lead')}</p>

            <div className="hero-actions">
              <Link className="btn btn-primary" to="/contact">{t('home.ctaTalk')}</Link>
              <Link className="btn btn-secondary" to="/projects">{t('home.ctaProjects')}</Link>
            </div>

            <div className="hero-stat-grid">
              <article className="hero-stat panel panel--pad">
                <span className="hero-stat__label">{t('home.stats.specialtyLabel')}</span>
                <strong>{t('home.stats.specialtyValue')}</strong>
              </article>
              <article className="hero-stat panel panel--pad">
                <span className="hero-stat__label">{t('home.stats.focusLabel')}</span>
                <strong>{t('home.stats.focusValue')}</strong>
              </article>
              <article className="hero-stat panel panel--pad">
                <span className="hero-stat__label">{t('home.stats.modeLabel')}</span>
                <strong>{t('home.stats.modeValue')}</strong>
              </article>
            </div>
          </div>

          <div className="home-hero__visual panel">
            <div className="home-hero__image-wrap">
              <img src={heroImg} alt={t('home.imageAlt')} className="home-hero__image" loading="lazy" />
            </div>
            <div className="home-hero__note">
              <span className="home-hero__note-label">{t('home.noteLabel')}</span>
              <p>{t('home.noteText')}</p>
            </div>
          </div>
        </div>
      </section>

      <section className="page-shell section-block">
        <div className="section-heading">
          <div>
            <span className="eyebrow">{t('home.focus.eyebrow')}</span>
            <h2 className="section-title">{t('home.focus.title')}</h2>
          </div>
          <p className="section-caption">{t('home.focus.caption')}</p>
        </div>

        <div className="feature-grid">
          {focusAreas.map((area) => (
            <article key={area.title} className="feature-card panel panel--pad">
              <p className="panel-kicker">{area.title}</p>
              <p>{area.description}</p>
            </article>
          ))}
        </div>
      </section>

      <section className="page-shell section-block">
        <div className="section-heading">
          <div>
            <span className="eyebrow">{t('home.skills.eyebrow')}</span>
            <h2 className="section-title">{t('home.skills.title')}</h2>
          </div>
        </div>

        <div className="expertise-grid">
            {skills.map((skill) => (
              <article key={skill.title} className="skill-panel panel panel--pad">
                <p className="panel-kicker">{skill.title}</p>
                <ul className="bullet-list skill-panel__list">
                  {skill.items.map((item) => (
                    <li key={item}>{item}</li>
                  ))}
                </ul>
              </article>
            ))}
        </div>
      </section>

      <section className="page-shell section-block">
        <div className="section-heading">
          <div>
            <span className="eyebrow">{t('home.projects.eyebrow')}</span>
            <h2 className="section-title">{t('home.projects.title')}</h2>
          </div>
          <Link to="/projects" className="btn btn-secondary">{t('home.projects.seeAll')}</Link>
        </div>

        <div className="card-grid home-project-grid">
          {featuredProjects.map((project) => (
            <ProjectCard key={project.id} {...project} />
          ))}
        </div>
      </section>

      <section className="page-shell section-block">
        <div className="cta-band panel panel--pad">
          <div>
            <span className="eyebrow">{t('home.cta.eyebrow')}</span>
            <h2 className="section-title">{t('home.cta.title')}</h2>
            <ul className="bullet-list cta-band__list">
              {serviceHighlights.map((item) => (
                <li key={item}>{item}</li>
              ))}
            </ul>
          </div>

          <div className="cta-band__actions">
            <Link className="btn btn-primary" to="/services">{t('home.cta.explore')}</Link>
            <Link className="btn btn-secondary" to="/about">{t('home.cta.profile')}</Link>
          </div>
        </div>
      </section>
    </main>
  );
};

export default Home;
